create table public.manual_chapter_index(id text primary key,title text not null,printed_pages text not null,pdf_start integer not null,pdf_end integer not null,source_hash text not null,check(pdf_start>0 and pdf_end>=pdf_start and pdf_end<=472));
alter table public.manual_chapter_index enable row level security;
revoke all on public.manual_chapter_index from public,anon,authenticated;
grant select on public.manual_chapter_index to anon,authenticated;
create policy manual_chapters_read on public.manual_chapter_index for select to anon,authenticated using(true);
alter table public.threads add column manual_chapter_id text references public.manual_chapter_index;
create index threads_manual_chapter on public.threads(manual_chapter_id,created_at desc);
